void PageHandlerAsyncWaiter::GetBookmarkBar(
    std::vector<BookmarkDataPtr>* out_bookmarks) {
  base::RunLoop loop;
  proxy_->GetBookmarkBar(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<BookmarkDataPtr>* out_bookmarks
,
             std::vector<BookmarkDataPtr> bookmarks) {*out_bookmarks = std::move(bookmarks);
            loop->Quit();
          },
          &loop,
          out_bookmarks));
  loop.Run();
}

